  function cleanToken(value) {
    return String(value || "")
      .replace(/[.،؟!؛,:"“”«»()]/g, "")
      .trim();
  }

  function glossToken(value) {
    const word = cleanToken(value);
    const morphology = morphemes[word] || null;
    return {
      word,
      latin: uly.transliterateUyghur(word),
      meaning: meanings[word] || "词义待补充",
      known: Object.hasOwn(meanings, word),
      segments: (morphology?.segments || []).map((segment) => ({
        ...segment,
        word: segment.surface,
        latin: uly.transliterateUyghur(segment.surface),
        baseLatin: uly.transliterateUyghur(segment.base.replace(/ـ/g, ""))
      })),
      formation: morphology?.formation ? { ...morphology.formation } : null
    };
  }

  function glossSentence(value) {
    return String(value || "")
      .replace(/[.،؟!؛,:"“”«»()]/g, " ")
      .split(/\s+/)
      .filter(Boolean)
      .map(glossToken);
  }

  window.ANA_TILIM_SENTENCE_GLOSSARY = Object.freeze({
    glossSentence,
    glossToken
  });
